function setup() {
  createCanvas(windowWidth, windowHeight);
  // disables scaling for retina screens which can create inconsistent scaling between displays
  pixelDensity(1);
  noStroke();

  // shaders require WEBGL mode to work
  shaderBg = createGraphics(width, height, WEBGL);

  // --- Create Shader Selector Dropdown ---
  shaderSelector = createSelect();
  shaderSelector.parent('shader-controls'); // Attach to the div in index.html
  shaderSelector.position(10, 10); // Position it on the canvas (adjust as needed)
  shaderSelector.addClass('shader-dropdown'); // Add a class for styling

  // Add options for each shader variant
  shaderSelector.option('P5/GLSL Shader 001', 1);
  shaderSelector.option('P5/GLSL Shader 002', 2);
  shaderSelector.option('P5/GLSL Shader 003', 3);
  shaderSelector.option('P5/GLSL Shader 004', 3);
  shaderSelector.option('P5/GLSL Shader 005', 4);
  shaderSelector.option('P5/GLSL Shader 006', 5);
  shaderSelector.option('P5/GLSL Shader 007', 6);
  shaderSelector.option('P5/GLSL Shader 008', 7);
  shaderSelector.option('P5/GLSL Shader 009', 8);
  shaderSelector.option('P5/GLSL Shader 010', 9);
  shaderSelector.option('P5/GLSL Shader 011', 10);
  shaderSelector.option('P5/GLSL Shader 012', 11);

  // Set default selection (e.g., Code 00)
  shaderSelector.selected(1);
  // Attach a change listener to the dropdown
  shaderSelector.changed(shaderChanged);

  // Initialize the shader choice when setup runs
