// Function called when the shader selector dropdown changes
function shaderChanged() {
  let selectedShaderIndex = parseInt(shaderSelector.value());
//	console.log("Selected Shader:", selectedShaderIndex);
  theShader.setUniform("u_shader_choice", selectedShaderIndex);
