/* === 4K MV Pure Canvas - 全域控制項與 UI 面板極限無痕隱藏 === */
.dg, .lil-gui, .qs_main, .opc-control, #opc-control-panel, .control-panel, .gui-container,
.tp-dfwv, .tp-rotv, .tweakpane, [class*='tp-'], [class*='tweakpane'],
[class*='gui'], [id*='gui'], [class*='control'], [id*='control'],
[class*='instruction'], [id*='instruction'], [class*='info'], [id*='info'],
[class*='fps'], [id*='fps'], [class*='overlay'], [id*='overlay'],
[class*='panel'], [id*='panel'], [class*='toolbar'], [id*='toolbar'],
.p5-control, .ui-container, #ui, #controls, .hud, [class*='hud'],
input, button, select, textarea, label, form, nav, header {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
  pointer-events: none !important;
  width: 0 !important;
  height: 0 !important;
  position: absolute !important;
  left: -9999px !important;
  top: -9999px !important;
}
html,
body {
  margin: 0;
  padding: 0;
  overflow: hidden;/* Prevent scrollbars due to dropdown positioning or canvas overflow */
  font-family: sans-serif;/* A basic font for readability */
}

/* Style for the shader selection dropdown */
.shader-dropdown {
  position: absolute;
  top: 10px;
  left: 10px;
  padding: 8px 12px;
  font-size: 16px;
  background-color: rgba(50, 50, 50, 0.8);/* Dark semi-transparent background */
  color: white;
  border: 1px solid #333;
  border-radius: 5px;
  cursor: pointer;
  z-index: 100;/* Ensure it's above the canvas */
}

.shader-dropdown:hover {
  background-color: rgba(70, 70, 70, 0.9);
}

.shader-dropdown option {
  background-color: #222;/* Dark background for options */
  color: white;
  padding: 5px;
}
